import sys,json,time,os,math
from pathlib import Path
import numpy as np
from PIL import Image
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot
OUT=Path('/app/output'); Q=np.array([0.,1.,0.,0.])
class Painter:
 def __init__(self):
  self.r=Robot();self.spec=self.r.spec();o=self.r.get_obs(cameras=[],video='none');self.pos=np.array(o.meta['proprio']['now'][7:10]);self.buf=[];self.index=len(list(OUT.glob('call_*.json')))
 def flush(self):
  if not self.buf:return
  a=np.array(self.buf);self.buf=[];before=self.r.status()
  np.save(OUT/f'actions_{self.index:05}.npy',a)
  try:r=self.r.submit('ee_pose',a,dt=.05,cameras=[],video='none')
  except Exception:
   st=self.r.wait_ready()
   if st['control_steps']==before['control_steps']:r=self.r.submit('ee_pose',a,dt=.05,cameras=[],video='none')
   else:raise RuntimeError('Ambiguous execution; inspect status before continuing')
  (OUT/f'call_{self.index:05}.json').write_text(json.dumps(r.meta));self.index+=1
  if r.stopped:raise RuntimeError('Call stopped early')
  if r.meta.get('plan'):
   fails=[p for p in r.meta['plan'] if p.get('ik_failures',0)]
   if fails:print('IK',fails,flush=True)
  return r
 def move(self,p,speed=.10,hold=0):
  p=np.array(p,float);n=max(1,int(np.ceil(np.linalg.norm(p-self.pos)/(speed*.05))))
  for x in np.linspace(self.pos,p,n+1)[1:]:
   self.buf.append([*x,*Q])
   if len(self.buf)>=180:self.flush()
  self.pos=p
  for _ in range(round(hold/.05)):
   self.buf.append([*p,*Q])
   if len(self.buf)>=180:self.flush()
 def park(self):
  self.move([*self.pos[:2],.07],hold=.2);self.move([-.30,0,.10],hold=.5);self.flush()
 def observe(self,name,cameras=['canvas_cam','practice_cam','scene_cam','side_cam'],depth=False):
  self.flush();o=self.r.get_obs(cameras=cameras,depth=depth);o.save(str(OUT/name))
  for c,im in o.last.items():Image.fromarray(im).save(OUT/f'{name}_{c}.png')
  print(name,self.r.status(),flush=True);return o
if __name__=='__main__':
 p=Painter();p.park();p.observe('clear',depth=True)
